.sl-feature-grid {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3rem, 6vw, 5.5rem);
}
.sl-feature-grid h2,
.sl-feature-grid h3 {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-feature-grid .sl-text-primary { color: var(--smartlearn-primary); }
.sl-feature-grid .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-feature-grid .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-feature-grid .sl-bg-card {
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
    border-radius: var(--smartlearn-radius, 1rem);
}
.sl-feature-grid .sl-border { border-color: var(--smartlearn-card-border); }
.sl-feature-grid .sl-grid-subtitle { max-width: 600px; }
.sl-feature-grid .sl-card-img-wrapper { height: 200px; }
.sl-feature-grid .sl-media-fallback {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text-muted);
}
.sl-feature-grid .sl-grid-card {
    transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
}
.sl-feature-grid .sl-grid-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 1rem 2.5rem color-mix(in srgb, var(--smartlearn-text) 10%, transparent);
    border-color: var(--smartlearn-primary);
}
.sl-feature-grid .sl-zoom-img {
    transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.sl-feature-grid .sl-grid-card:hover .sl-zoom-img {
    transform: scale(1.08);
}
.sl-feature-grid .sl-icon-wrapper {
    width: 48px;
    height: 48px;
    margin-top: -40px;
    position: relative;
    z-index: 2;
    border: 4px solid var(--smartlearn-card-bg);
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 14%, var(--smartlearn-card-bg));
    transition: background-color 0.3s ease, color 0.3s ease;
}
.sl-feature-grid .sl-grid-card:hover .sl-icon-wrapper {
    background-color: var(--smartlearn-primary);
    color: var(--smartlearn-btn-text);
}
@media (prefers-reduced-motion: reduce) {
    .sl-feature-grid .sl-grid-card,
    .sl-feature-grid .sl-zoom-img,
    .sl-feature-grid .sl-icon-wrapper {
        transition: none;
    }
    .sl-feature-grid .sl-grid-card:hover,
    .sl-feature-grid .sl-grid-card:hover .sl-zoom-img {
        transform: none;
    }
}
